import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Button } from "@heroui/react";
import {
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectAsyncSelect,
  CustomSelectReactSelect,
  FileUploader,
  CustomTextArea,
  Loading,
  CustomDatePicker,
  CustomSwitch,
} from "../../../components";
import { useFormik } from "formik";
import useApi from "../../../hooks/useApi";
import { ToastContainer, toast } from "react-toastify";
import { Image, Modal } from "antd";
import propertyDisposalTypes from "../../../data/propertyDisposalTypes";
import propertyTypes from "../../../data/propertyTypes";
import countiesApi from "../../../api/countiesApi";
import propertiesApi from "../../../api/properties/propertiesApi";
import { useStateContext } from "../../../contexts/ContextProvider";
import usersApi from "../../../api/usersApi";
import dayjs from "dayjs";
export default function PropertyFormModal({
  ismodalOpen,
  setisModalOpen,
  tenantToEdit,
  modalTitle = "Add new tenant",
  updated,
  setUpdated,
}) {



  const [propertyUnitTenant, setPropertyUnitTenant] = useState(tenantToEdit ? tenantToEdit : null);
  const [errors, setErrors] = useState();
  const { loggedInUser } = useStateContext()








  const createPropertyUnitTenantApi = useApi(propertiesApi.createPropertyUnitTenantAction)
  const createPropertyUnitTenant = async (data) => {

    await createPropertyUnitTenantApi.request(data)
  }

  const updatePropertyUnitTenantApi = useApi(propertiesApi.updatePropertyUnitTenantAction)
  const updatePropertyUnitTenant = async (data, id) => {
    await updatePropertyUnitTenantApi.request(data, id)
  }
  useEffect(() => {
    if (createPropertyUnitTenantApi.data && createPropertyUnitTenantApi.data.response_code === 0) {
      toast.success(createPropertyUnitTenantApi.data.response_message);
      setisModalOpen(false);
      setUpdated(!updated);
    }
    console.log("createPropertyUnitTenantApi.data", createPropertyUnitTenantApi.data);
  }, [createPropertyUnitTenantApi.data]);



  useEffect(() => {
    if (updatePropertyUnitTenantApi.data && updatePropertyUnitTenantApi.data.response_code === 0) {
      toast.success(updatePropertyUnitTenantApi.data.response_message);
      setisModalOpen(false);
      setUpdated(!updated);
    }
    console.log("updatePropertyApi.data", updatePropertyUnitTenantApi.data);

    if (updatePropertyUnitTenantApi.data && updatePropertyUnitTenantApi.data.response_code === 1) {
      toast.error(updatePropertyUnitTenantApi.data.response_message)
    }
  }, [updatePropertyUnitTenantApi.data]);


  //Get properties
  const [properties, setProperties] = useState([])
  const propertiesActionsApi = useApi(propertiesApi.propertiesAction)

  const getProperties = async () => {
    await propertiesActionsApi.request({
      "action": "GetEntityProperties"

    })
  }


  useEffect(() => {
    getProperties()
  }, [])


  useEffect(() => {
    if (propertiesActionsApi.data && propertiesActionsApi.data.length) {
      setProperties(propertiesActionsApi.data.map((i) => ({ label: i.title, value: i.id })));
    }

    console.log("propertiesActionsApi.data", propertiesActionsApi.data);
  }, [propertiesActionsApi.data]);


  const formik = useFormik({
    initialValues: {



     
      is_active: propertyUnitTenant ? propertyUnitTenant.is_active : "true",
      lease_start: propertyUnitTenant
        ? propertyUnitTenant.lease_start
        : dayjs().format("YYYY-MM-DD"),
      lease_end: propertyUnitTenant
        ?propertyUnitTenant.lease_end
        : dayjs().format("YYYY-MM-DD"),

      property_unit: propertyUnitTenant
        ? { label: propertyUnitTenant.property_unit_title, value: propertyUnitTenant.property_unit }
        : { label: "Select property unit", value: "" },
      property: propertyUnitTenant
        ? { label: propertyUnitTenant.property_title, value: propertyUnitTenant.property }
        : { label: "Select property", value: "" },
      tenant: propertyUnitTenant
        ? { label: `${propertyUnitTenant.first_name} ${propertyUnitTenant.last_name}`, value: propertyUnitTenant.tenant }
        : { label: "Search user by phone number", value: "" },

    },

    validationSchema: Yup.object({
      tenant: Yup.object()

        .required("Tenant ID is required"),
      lease_start: Yup.string()
        .min(3, "Must be 3 characters or more")
        .required("Tenant ID is required"),


    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      //Generate form data to automatically encode data for upload using axios
      let data = new FormData();
      console.log("VALZ", values);


      data.append("lease_end", values.lease_end);
      data.append("lease_start", values.lease_start);
      data.append("is_active", values.is_active);
      data.append("property_unit", values.property_unit.value);
      data.append("contract", values.contract);
      data.append("tenant", values.tenant.value);





      if (tenantToEdit) {
        updatePropertyUnitTenant(data, tenantToEdit.id);
      } else {
        createPropertyUnitTenant(data);
      }
    },
  });






  const handleOk = () => {
    setisModalOpen(false);
  };
  const handleCancel = () => {
    setisModalOpen(false);
  };


  const searchUsersApi = useApi(usersApi.usersAction);

  const [users, setUsers] = useState([])

  const searchUsers = async (data) => {
    await searchUsersApi.request(data);
  };

  const loadUserOptions = async (inputText = "", callback) => {
    searchUsers({
      action: "SearchUsers",
      searchQuery: inputText,
    });

    callback(users.map((i) => ({ label: `${i.title} - ${i.phone} `, value: i.id })));
  };


  const handleLeaseStartChange = (date, dateString) => {
    formik.setFieldValue("lease_start", dateString);
  };
  const handleLeaseEndChange = (date, dateString) => {
    formik.setFieldValue("lease_end", dateString);
  };

  useEffect(() => {
    if (searchUsersApi.data && searchUsersApi.data.length) {
      setUsers(searchUsersApi.data);
    }
    console.log("searchUsersApi.data", searchUsersApi.data);
  }, [searchUsersApi.data]);

  const [switchLabel, setswitchLabel] = useState("Active");
  const handleSwitchChange = (checked) => {

    formik.setFieldValue("is_active", checked ? "true" : "false");
    setswitchLabel(checked ? "Still a resident" : "Has vacated");

    // console.log('eee', e.target.checked)
  };

  const [propertyUnits, setpropertyUnits] = useState([])
  const propertyUnitsActionsApi = useApi(propertiesApi.propertiesAction)
  const retrievePropertyUnits = async (propertyId) => {
    await propertyUnitsActionsApi.request({
      action: "GetPropertyUnits",
      property_id: propertyId
    })
  }

  useEffect(() => {

    if (propertyUnitsActionsApi.data && propertyUnitsActionsApi.data.length) {
      setpropertyUnits(propertyUnitsActionsApi.data.map((i) => ({ label: i.title, value: i.id })));
    }


  }, [propertyUnitsActionsApi.data]);

  useEffect(() => {

    if (formik.values.property && formik.values.property.value) {
      console.log("selected property", formik.values.property);
      retrievePropertyUnits(formik.values.property.value);
    }


  }, [formik.values.property]);


  const handleFileChange = (e) => {
    e.preventDefault();
    console.log("file", e.target.files[0]);
    formik.setFieldValue("contract", e.target.files[0]);
  }


  return (
    <div className="w-full">
      <Modal
        maskClosable={false}
        width={720}
        className="w-full text-center"
        title={tenantToEdit ? `EDIT ${tenantToEdit.title}` : modalTitle}
        open={ismodalOpen}
        onOk={handleOk}
        onCancel={handleCancel}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />

        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className="flex flex-col items-center justify-center"

        >
          <div className="grid grid-cols-1 gap-1 w-full">

            <CustomFormItem
              touched={formik.touched.property}
              error={formik.errors.property}
            >
              <CustomSelectReactSelect
                className="text-start"
                name="property"
                id="property"
                label="Select property"
                size="large"
                onChange={(value) => formik.setFieldValue("property", value)}
                value={formik.values.property}
                placeholder="Select property"
                options={properties}
              />
            </CustomFormItem>


            {propertyUnits && propertyUnits.length ? <CustomFormItem
              touched={formik.touched.property_unit}
              error={formik.errors.property_unit}
            >
              <CustomSelectReactSelect
                className="text-start"
                name="property_unit"
                id="property_unit"
                label="Select property unit"
                size="large"
                onChange={(value) => formik.setFieldValue("property_unit", value)}
                value={formik.values.property_unit}
                placeholder="Select property unit"
                options={propertyUnits}
              />
            </CustomFormItem> : <div></div>}

            <CustomFormItem
              touched={formik.touched.tenant}
              error={formik.errors.tenant}
            >
              <CustomSelectAsyncSelect
                placeholder="Search  user by phone number"
                isClearable
                value={formik.values.tenant}
                onChange={(value) => formik.setFieldValue("tenant", value)}
                loadOptions={loadUserOptions}
              />
            </CustomFormItem>

            <CustomFormItem
              touched={formik.touched.lease_start}
              error={formik.errors.lease_start}
            >
              <CustomDatePicker
                id="lease_start"
                name="lease_start"
                size="large"
                placeholder="Select lease start date"
                defaultValue={dayjs(formik.values.lease_start, "YYYY-MM-DD")}
                onChange={handleLeaseStartChange}
              />
            </CustomFormItem>

            <CustomFormItem
              touched={formik.touched.lease_end}
              error={formik.errors.lease_end}
            >
              <CustomDatePicker
                id="lease_end"
                name="lease_end"
                size="large"
                placeholder="Select lease start date"
                defaultValue={dayjs(formik.values.lease_end, "YYYY-MM-DD")}
                onChange={handleLeaseEndChange}
              />
            </CustomFormItem>




            <CustomFormItem
              touched={formik.touched.contract}
              error={formik.errors.contract}
            >
              <CustomInput
                accept="application/pdf"
                required={true}
                id="contract"
                name="contract"
                onChange={handleFileChange}
                placeholder="Upload contract (as pdf)"
                size="large"
                type="file"
                
                label="Upload contract (as pdf)"
              />
            </CustomFormItem>
            <CustomFormItem
              touched={formik.touched.is_active}
              error={formik.errors.is_active}
            >
              <CustomSwitch
                id="is_active"
                checked={formik.values.is_active === "true"}
                onChange={(e) => handleSwitchChange(e)}
                title={switchLabel}
                checkedChildren="Still a resident"
                unCheckedChildren="Has vacated"
              />
            </CustomFormItem>
            <div className="w-full items-center mt-2">
              <Button className="w-36 rounded-md" color="primary" type="submit">
                Submit
              </Button>
            </div>
          </div>




        </CustomForm>
      </Modal>
    </div>
  );
}
